// src/routes/login/+page.server.ts
import { redirect } from '@sveltejs/kit';

export const actions = {
  default: async ({ request, fetch }) => {
    const data = await request.formData();
    const email = data.get('email');
    const password = data.get('password');

    const res = await fetch('https://your-app.bigbase.click/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password })
    });

    if (!res.ok) throw new Error('Login failed');
    const { token, user } = await res.json();

    // Store JWT in httpOnly cookie
    return { token, user };
  }
};

// src/hooks/useAuth.ts
import { useState } from 'react';

const BASE = 'https://your-app.bigbase.click';

export function useAuth() {
  const [user, setUser] = useState(null);

  const login = async (email: string, password: string) => {
    const res = await fetch(`${BASE}/api/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password })
    });
    const { token, user } = await res.json();
    localStorage.setItem('token', token);
    setUser(user);
    return user;
  };

  return { user, login };
}

// app/login/actions.ts
'use server'
import { cookies } from 'next/headers';

const BASE = 'https://your-app.bigbase.click';

export async function login(email: string, password: string) {
  const res = await fetch(`${BASE}/api/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  const { token, user } = await res.json();
  (await cookies()).set('token', token, { httpOnly: true, secure: true });
  return user;
}

// src/lib/api.ts
const BASE = 'https://your-app.bigbase.click';
const TOKEN = 'your-jwt-token';

export const db = {
  collection(name: string) {
    const headers = {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${TOKEN}`
    };
    return {
      list: async () => {
        const res = await fetch(`${BASE}/api/collections/${name}`, { headers });
        return res.json();
      },
      create: async (data: any) => {
        const res = await fetch(`${BASE}/api/collections/${name}`, {
          method: 'POST', headers, body: JSON.stringify({ data })
        });
        return res.json();
      },
      get: async (id: string) => {
        const res = await fetch(`${BASE}/api/collections/${name}/${id}`, { headers });
        return res.json();
      },
      update: async (id: string, data: any) => {
        const res = await fetch(`${BASE}/api/collections/${name}/${id}`, {
          method: 'PATCH', headers, body: JSON.stringify({ data })
        });
        return res.json();
      },
      delete: async (id: string) => {
        const res = await fetch(`${BASE}/api/collections/${name}/${id}`, {
          method: 'DELETE', headers
        });
        return res.json();
      }
    };
  }
};

// src/lib/api.ts
const BASE = 'https://your-app.bigbase.click';

function headers() {
  const token = localStorage.getItem('token');
  return {
    'Content-Type': 'application/json',
    ...(token && { Authorization: `Bearer ${token}` })
  };
}

export const db = {
  collection(name: string) {
    return {
      list: () => fetch(`${BASE}/api/collections/${name}`, { headers: headers() }).then(r => r.json()),
      create: (data: any) => fetch(`${BASE}/api/collections/${name}`, {
        method: 'POST', headers: headers(), body: JSON.stringify({ data })
      }).then(r => r.json()),
      get: (id: string) => fetch(`${BASE}/api/collections/${name}/${id}`, { headers: headers() }).then(r => r.json()),
      update: (id: string, data: any) => fetch(`${BASE}/api/collections/${name}/${id}`, {
        method: 'PATCH', headers: headers(), body: JSON.stringify({ data })
      }).then(r => r.json()),
      delete: (id: string) => fetch(`${BASE}/api/collections/${name}/${id}`, {
        method: 'DELETE', headers: headers()
      }).then(r => r.json())
    };
  }
};

// src/lib/storage.ts
const BASE = 'https://your-app.bigbase.click';
const TOKEN = 'your-jwt-token';

export const storage = {
  upload: async (bucket: string, file: File) => {
    const form = new FormData();
    form.append('file', file);
    const res = await fetch(`${BASE}/api/storage/buckets/${bucket}/files`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${TOKEN}` },
      body: form
    });
    return res.json();
  },
  download: async (bucket: string, fileId: string) => {
    const res = await fetch(`${BASE}/api/storage/buckets/${bucket}/files/${fileId}`, {
      headers: { Authorization: `Bearer ${TOKEN}` }
    });
    return res.blob();
  },
  list: async (bucket: string) => {
    const res = await fetch(`${BASE}/api/storage/buckets/${bucket}/files`, {
      headers: { Authorization: `Bearer ${TOKEN}` }
    });
    return res.json();
  }
};

// src/lib/realtime.ts
export function subscribe(collection: string, onUpdate: (data: any) => void) {
  const ws = new WebSocket(`wss://your-app.bigbase.click/api/realtime`);

  ws.onopen = () => {
    ws.send(JSON.stringify({ type: 'subscribe', collection }));
  };

  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.collection === collection) {
      onUpdate(msg.data);
    }
  };

  return () => ws.close();
}

// src/hooks/useRealtime.ts
import { useEffect } from 'react';

export function useRealtime(collection: string, onUpdate: (data: any) => void) {
  useEffect(() => {
    const ws = new WebSocket(`wss://your-app.bigbase.click/api/realtime`);
    ws.onopen = () => ws.send(JSON.stringify({ type: 'subscribe', collection }));
    ws.onmessage = (e) => {
      const msg = JSON.parse(e.data);
      if (msg.collection === collection) onUpdate(msg.data);
    };
    return () => ws.close();
  }, [collection]);
}
